(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-721":{scenario:{company:"Bệnh viện Đa khoa Phú Lâm Viên",supervisor:{name:"Trịnh Văn Lâm",role:{vi:"Trưởng phòng Vật tư - Thiết bị y tế",en:"Head of Medical Equipment Department"}},ref_code:"WO-6143",title:{vi:"Đúng phân loại. Đúng phép thử. Đúng tem kiểm tra.",en:"Right class. Right test. Right inspection tag."},brief:{vi:"Đây là tình huống đào tạo. Bạn hoàn tất phiếu bảo trì WO-6143 cho bơm truyền dịch thể tích IP-27 của khoa Hồi sức tích cực. Phép thử lưu lượng cài 25 mL/h trong 120 phút cho thể tích tích lũy 23.6 mL ở phút 60 và 48.1 mL ở phút 120. Dùng terminal để chẩn đoán, sửa loại bộ phận ứng dụng và lưu lượng trung bình trên phiếu, rồi lập báo cáo có căn cứ.",en:"This is a training scenario. You are closing work order WO-6143 for volumetric infusion pump IP-27 in the intensive care unit. The flow test at 25 mL/h over 120 minutes gave cumulative volumes of 23.6 mL at minute 60 and 48.1 mL at minute 120. Use the terminal to diagnose, correct the applied part type and the mean flow on the work order, then write an evidence-based report."},reference_title:{vi:"Hồ sơ kỹ thuật & biên bản thử đã duyệt · WO-6143",en:"Approved technical file & test record · WO-6143"},fields:[{id:"APPLIED_PART",label:{vi:"Loại bộ phận ứng dụng",en:"Applied part type"},initial:"Type BF",expected:"Type CF",choices:["Type B","Type BF","Type CF"],reference:"Nhãn thiết bị và hồ sơ kỹ thuật",hint:{vi:"Đọc ký hiệu trên nhãn: hình người, hình người trong ô vuông và hình trái tim trong ô vuông là ba loại khác nhau.",en:"Read the label symbol: a figure, a figure in a square and a heart in a square are three different types."}},{id:"FLOW_H2",label:{vi:"Lưu lượng trung bình giờ thứ 2 (mL/h)",en:"Second-hour mean flow (mL/h)"},initial:"24.05",expected:"24.5",reference:"Biên bản thử lưu lượng",ref_value:{vi:"Cài 25 mL/h; tích lũy 23.6 mL tại phút 60 và 48.1 mL tại phút 120",en:"Set 25 mL/h; cumulative 23.6 mL at minute 60 and 48.1 mL at minute 120"},hint:{vi:"Loại bỏ giờ đầu là giai đoạn khởi động, chỉ tính thể tích trong cửa sổ phân tích.",en:"Exclude the first hour start-up period and use only the volume in the analysis window."}}],sop32:{vi:"Lưu lượng trung bình = (thể tích tích lũy phút 120 - thể tích tích lũy phút 60) / 1 giờ; sai số = (lưu lượng đo - lưu lượng cài) / lưu lượng cài, dung sai ±5% (mô phỏng).",en:"Mean flow = (cumulative volume at minute 120 - cumulative volume at minute 60) / 1 hour; error = (measured - set) / set, tolerance ±5% (training value)."},context:{label:"CMMS / WO-6143",metrics:[{label:{vi:"Lưu lượng cài",en:"Set flow"},value:"25 mL/h"},{label:{vi:"Thời gian thử",en:"Test duration"},value:"120 min"},{label:{vi:"Dòng rò một lỗi",en:"Single fault leakage"},value:"62 µA"}]},terminal:{system:"biomed-cmms",settable:["APPLIED_PART","FLOW_H2"],commands:[{cmd:"status",out:{vi:"WO-6143: bơm IP-27, khoa Hồi sức tích cực, bảo trì định kỳ 12 tháng. An toàn điện đã chạy với cấu hình Type BF; thử lưu lượng hoàn tất 120 phút.",en:"WO-6143: pump IP-27, intensive care unit, 12-month preventive maintenance. Electrical safety ran with the Type BF profile; flow test completed over 120 minutes."}},{cmd:"cat nameplate.txt",out:{vi:"Nhãn máy: ký hiệu trái tim trong ô vuông, hai bên có hình bản cực (chống sốc tim); Class I; 220-240 V 50/60 Hz.",en:"Label: heart-in-a-square symbol with paddles on both sides (defibrillation-proof); Class I; 220-240 V 50/60 Hz."}},{cmd:"esa report",out:{vi:"Dòng rò bệnh nhân: bình thường 7 µA; một lỗi (hở trung tính) 62 µA. Giới hạn đang nạp 100/500 µA (Type BF). Kết luận tự động: PASS.",en:"Patient leakage: normal condition 7 µA; single fault (open neutral) 62 µA. Loaded limits 100/500 µA (Type BF). Automatic verdict: PASS."}},{cmd:"flowtest log",out:{vi:"Cài 25 mL/h. Thể tích tích lũy: phút 30 = 11.4 mL; phút 60 = 23.6 mL; phút 90 = 35.9 mL; phút 120 = 48.1 mL.",en:"Set 25 mL/h. Cumulative volume: minute 30 = 11.4 mL; minute 60 = 23.6 mL; minute 90 = 35.9 mL; minute 120 = 48.1 mL."}},{cmd:"cat limits.txt",out:{vi:"Giới hạn dòng rò bệnh nhân (AC): Type B và BF 100 µA bình thường, 500 µA một lỗi; Type CF 10 µA bình thường, 50 µA một lỗi.",en:"Patient leakage limits (AC): Type B and BF 100 µA normal, 500 µA single fault; Type CF 10 µA normal, 50 µA single fault."}}]},crisis:{vi:"Trưởng khoa Hồi sức nhắn: “Khoa đang thiếu bơm, cứ dán tem Đạt cho IP-27 theo kết luận PASS của máy đo, an toàn điện đo lại sau. Có gì tôi chịu trách nhiệm.”",en:"The ICU head messages you: “We are short of pumps. Put a Pass tag on IP-27 based on the analyser's PASS and redo electrical safety later. I take responsibility.”"},options:{safe:{vi:"Không dán tem Đạt; gắn nhãn Không sử dụng, đo lại với cấu hình đúng theo nhãn máy, báo trưởng phòng Vật tư - Thiết bị y tế và điều chuyển bơm dự phòng cho khoa.",en:"Do not apply a Pass tag; label it Do Not Use, retest with the profile matching the label, inform the equipment manager and send a backup pump to the unit."},shortcut:{vi:"Dán tem Đạt theo kết luận tự động của máy đo cho kịp, đo lại sau khi khoa trả máy.",en:"Apply the Pass tag from the automatic verdict now and retest when the unit returns the pump."},wait:{vi:"Để máy trên bàn sửa chữa, không ghi kết luận và chờ khoa tự gọi lại.",en:"Leave the pump on the bench with no verdict and wait for the unit to call again."}},questions:{vi:["Vì sao kết luận PASS tự động của máy phân tích an toàn điện không còn giá trị? Dữ liệu nào chứng minh?","Trình bày cách tính lưu lượng giờ thứ 2 và cách xử lý thiết bị không đạt khi khoa lâm sàng đang thiếu máy."],en:["Why is the analyser's automatic PASS verdict no longer valid? Which data proves it?","Explain how you calculated the second-hour flow and how you handle a failed device when the ward is short of equipment."]},hints:{vi:["Chạy cat nameplate.txt và so ký hiệu trên nhãn với cấu hình giới hạn mà máy đo đang nạp.","Theo SOP mục 3.2: chỉ dùng thể tích trong cửa sổ từ phút 60 đến phút 120.","Đọc lại SOP mục 4.2: thiết bị chưa đạt không được dán tem Đạt, phải cách ly và báo cáo."],en:["Run cat nameplate.txt and compare the label symbol with the limit profile loaded in the analyser.","Per SOP 3.2: use only the volume in the window from minute 60 to minute 120.","Re-read SOP 4.2: a device that has not passed must not get a Pass tag; quarantine and report it."]}},learning:{summary:{vi:"Kỹ sư thiết bị y tế quản lý vòng đời trang thiết bị trong bệnh viện: tiếp nhận, nghiệm thu, lắp đặt, bảo trì phòng ngừa, sửa chữa, hiệu chuẩn, kiểm tra an toàn điện và thanh lý. Mục tiêu là thiết bị luôn sẵn sàng, chính xác và an toàn cho người bệnh, người vận hành. Nghề đòi hỏi kiến thức điện tử y sinh, đọc tiêu chuẩn kỹ thuật, dùng thành thạo máy phân tích chuyên dụng và bản lĩnh từ chối đưa thiết bị chưa đạt vào sử dụng.",en:"A biomedical equipment engineer manages the life cycle of hospital equipment: receiving, acceptance testing, installation, preventive maintenance, repair, calibration, electrical safety testing and disposal. The goal is equipment that is always available, accurate and safe for patients and operators. The role needs biomedical electronics knowledge, the ability to read technical standards, skill with specialised analysers and the integrity to keep failed devices out of service."},responsibilities:{vi:["Lập và thực hiện kế hoạch bảo trì phòng ngừa theo mức rủi ro và khuyến cáo nhà sản xuất.","Kiểm tra an toàn điện, hiệu năng thiết bị bằng máy phân tích chuyên dụng sau bảo trì và sửa chữa.","Chẩn đoán, sửa chữa sự cố, quản lý phụ tùng và phối hợp với nhà cung cấp dịch vụ.","Nghiệm thu thiết bị mới, đào tạo người sử dụng và lưu hồ sơ kỹ thuật trên CMMS.","Theo dõi cảnh báo an toàn, thông báo thu hồi và báo cáo sự cố liên quan đến thiết bị."],en:["Plan and perform preventive maintenance by risk level and manufacturer recommendations.","Test electrical safety and performance with specialised analysers after maintenance and repair.","Diagnose and repair faults, manage spare parts and coordinate with service providers.","Run acceptance tests for new equipment, train users and keep technical records in the CMMS.","Track safety alerts and recalls and report equipment-related incidents."]},competencies:[{name:{vi:"An toàn điện y tế",en:"Medical electrical safety"},desc:{vi:"Xác định cấp bảo vệ, loại bộ phận ứng dụng và áp đúng giới hạn dòng rò khi thử nghiệm.",en:"Identify protection class and applied part type and apply the correct leakage limits."}},{name:{vi:"Kiểm tra hiệu năng",en:"Performance verification"},desc:{vi:"Đo lưu lượng, năng lượng, áp suất, thông số sinh lý và so với dung sai nhà sản xuất.",en:"Measure flow, energy, pressure and physiological parameters against manufacturer tolerances."}},{name:{vi:"Chẩn đoán sự cố",en:"Fault diagnosis"},desc:{vi:"Đọc nhật ký lỗi, sơ đồ mạch và khoanh vùng nguyên nhân gốc trước khi thay linh kiện.",en:"Read error logs and schematics and isolate the root cause before replacing parts."}},{name:{vi:"Quản lý rủi ro thiết bị",en:"Equipment risk management"},desc:{vi:"Ưu tiên bảo trì theo chức năng, rủi ro và lịch sử sự cố; cách ly thiết bị không đạt.",en:"Prioritise maintenance by function, risk and incident history; quarantine failed devices."}},{name:{vi:"Liêm chính kỹ thuật",en:"Technical integrity"},desc:{vi:"Chỉ dán tem khi đủ bằng chứng thử nghiệm, ghi hồ sơ trung thực và báo cáo áp lực sai quy trình.",en:"Tag equipment only with full test evidence, keep honest records and escalate improper pressure."}}],knowledge:{vi:["Nghị định 98/2021/NĐ-CP về quản lý trang thiết bị y tế, phân loại theo mức rủi ro A, B, C, D.","IEC 60601-1 về an toàn chung thiết bị điện y tế và IEC 62353 về thử nghiệm định kỳ, sau sửa chữa.","IEC 60601-2-24 về yêu cầu riêng cho bơm truyền dịch và bộ điều khiển truyền dịch.","ISO 14971 về quản lý rủi ro và ISO 13485 về hệ thống quản lý chất lượng trang thiết bị y tế.","Phương pháp bảo trì dựa trên rủi ro và chỉ số sẵn sàng, thời gian ngừng máy, thời gian sửa chữa trung bình."],en:["Decree 98/2021/ND-CP on medical device management, with risk classes A, B, C and D.","IEC 60601-1 on general safety of medical electrical equipment and IEC 62353 on recurrent and post-repair testing.","IEC 60601-2-24 on particular requirements for infusion pumps and controllers.","ISO 14971 on risk management and ISO 13485 on quality management systems for medical devices.","Risk-based maintenance and the metrics of availability, downtime and mean time to repair."]},tools:["Máy phân tích an toàn điện","Máy phân tích bơm truyền dịch","Máy phân tích máy phá rung tim","Bộ mô phỏng thông số người bệnh","Phần mềm CMMS quản lý thiết bị"],kpis:{vi:["Tỷ lệ bảo trì phòng ngừa hoàn thành đúng hạn (mục tiêu từ 95%).","Tỷ lệ sẵn sàng của thiết bị hỗ trợ sự sống.","Thời gian sửa chữa trung bình mỗi sự cố.","Số sự cố người bệnh liên quan đến thiết bị do lỗi bảo trì (mục tiêu bằng 0)."],en:["Preventive maintenance completed on time (target 95% or more).","Availability of life-support equipment.","Mean time to repair per fault.","Patient incidents caused by maintenance errors (target zero)."]},day:[{time:"07:30",vi:"Xem lệnh công việc trên CMMS, ưu tiên thiết bị hỗ trợ sự sống đang chờ sửa.",en:"Review CMMS work orders and prioritise life-support devices awaiting repair."},{time:"09:00",vi:"Bảo trì định kỳ bơm truyền dịch, chạy thử an toàn điện và thử lưu lượng.",en:"Service infusion pumps and run electrical safety and flow tests."},{time:"11:00",vi:"Xử lý cuộc gọi sự cố tại khoa Cấp cứu, khoanh vùng lỗi máy theo dõi người bệnh.",en:"Respond to a fault call in the emergency department and isolate a patient monitor fault."},{time:"14:00",vi:"Nghiệm thu thiết bị mới với nhà cung cấp và hướng dẫn điều dưỡng sử dụng.",en:"Run acceptance testing with the vendor and train nurses on the new device."},{time:"16:30",vi:"Cập nhật hồ sơ, dán tem kiểm tra cho thiết bị đạt và báo cáo thiết bị cách ly.",en:"Update records, tag passed equipment and report quarantined devices."}],mistakes:{vi:["Nạp sai cấu hình phân loại trên máy phân tích và tin vào kết luận tự động.","Tính lưu lượng trên toàn bộ thời gian thử, gồm cả giai đoạn khởi động.","Dán tem Đạt hoặc trả máy cho khoa trước khi hoàn tất đủ các phép thử."],en:["Loading the wrong classification profile on the analyser and trusting the automatic verdict.","Computing flow over the whole test including the start-up period.","Tagging a device as passed or returning it before all tests are complete."]},career:[{vi:"Kỹ thuật viên thiết bị y tế",en:"Medical equipment technician"},{vi:"Kỹ sư thiết bị y tế",en:"Biomedical equipment engineer"},{vi:"Kỹ sư chính, phụ trách nhóm thiết bị chuyên sâu",en:"Senior engineer for specialised equipment"},{vi:"Trưởng phòng Vật tư - Thiết bị y tế",en:"Head of medical equipment management"}],glossary:[{term:"Applied part",vi:"Bộ phận của thiết bị tiếp xúc trực tiếp với người bệnh khi sử dụng bình thường.",en:"Part of the equipment that contacts the patient in normal use."},{term:"Type CF",vi:"Bộ phận ứng dụng có mức bảo vệ cao nhất, dùng được khi có thể tiếp xúc trực tiếp với tim.",en:"Applied part with the highest protection level, suitable for possible direct cardiac contact."},{term:"Leakage current",vi:"Dòng điện không mong muốn chạy qua người bệnh, người vận hành hoặc vỏ máy.",en:"Unwanted current flowing through the patient, the operator or the enclosure."},{term:"Preventive maintenance",vi:"Bảo trì phòng ngừa theo lịch để phát hiện suy giảm trước khi gây hỏng hóc.",en:"Scheduled maintenance that detects degradation before it causes failure."},{term:"CMMS",vi:"Phần mềm quản lý bảo trì: danh mục thiết bị, lệnh công việc, lịch sử và phụ tùng.",en:"Maintenance management software for asset lists, work orders, history and spare parts."}],quiz:[{q:{vi:"Theo IEC 60601-1, giới hạn dòng rò bệnh nhân (AC) trong điều kiện một lỗi của bộ phận ứng dụng Type CF là bao nhiêu?",en:"Under IEC 60601-1, what is the AC patient leakage limit in single fault condition for a Type CF applied part?"},options:{vi:["500 µA","50 µA","100 µA","10 µA"],en:["500 µA","50 µA","100 µA","10 µA"]},answer:1,explain:{vi:"Type CF: 10 µA ở điều kiện bình thường và 50 µA ở điều kiện một lỗi; Type B và BF là 100 và 500 µA.",en:"Type CF: 10 µA in normal condition and 50 µA in single fault; Type B and BF are 100 and 500 µA."}},{q:{vi:"Bơm cài 50 mL/h, thể tích tích lũy phút 60 là 49.0 mL và phút 120 là 97.5 mL. Sai số lưu lượng giờ thứ 2 là bao nhiêu?",en:"A pump set at 50 mL/h shows 49.0 mL at minute 60 and 97.5 mL at minute 120. What is the second-hour flow error?"},options:{vi:["-2.5%","+1.0%","-1.0%","-3.0%"],en:["-2.5%","+1.0%","-1.0%","-3.0%"]},answer:3,explain:{vi:"Giờ thứ 2: 97.5 - 49.0 = 48.5 mL/h; sai số (48.5 - 50) / 50 = -3.0%.",en:"Second hour: 97.5 - 49.0 = 48.5 mL/h; error (48.5 - 50) / 50 = -3.0%."}},{q:{vi:"Khoa lâm sàng thiếu máy và yêu cầu dán tem Đạt trước khi bạn hoàn tất phép thử. Bạn làm gì?",en:"A ward short of devices asks you to tag a pump as passed before testing is complete. What do you do?"},options:{vi:["Giữ máy cách ly, báo cấp trên và điều chuyển thiết bị dự phòng","Dán tem rồi thử lại sau","Cho mượn máy không dán tem","Đề nghị khoa tự kiểm tra"],en:["Keep it quarantined, escalate and provide a backup device","Tag it now and retest later","Lend it without a tag","Ask the ward to test it themselves"]},answer:0,explain:{vi:"Tem Đạt là cam kết an toàn; thiết bị chưa đủ bằng chứng phải cách ly, báo cáo và thay bằng thiết bị dự phòng.",en:"A Pass tag is a safety commitment; a device without full evidence must be quarantined, reported and replaced by a backup."}},{q:{vi:"Theo Nghị định 98/2021/NĐ-CP, trang thiết bị y tế được phân loại theo mức độ rủi ro như thế nào?",en:"How does Decree 98/2021/ND-CP classify medical devices by risk?"},options:{vi:["Hai loại: thường và đặc biệt","Ba loại: I, II, III","Bốn loại: A, B, C, D","Năm nhóm theo chuyên khoa"],en:["Two types: ordinary and special","Three classes: I, II, III","Four classes: A, B, C, D","Five groups by specialty"]},answer:2,explain:{vi:"Nghị định 98/2021/NĐ-CP phân trang thiết bị y tế thành loại A, B, C, D, trong đó A có mức rủi ro thấp nhất.",en:"Decree 98/2021/ND-CP sorts medical devices into classes A, B, C and D, with A the lowest risk."}}],tools_en:["Electrical safety analyzer","Infusion pump analyzer","Defibrillator analyzer","Patient vital signs simulator","CMMS for medical equipment management"]}}})})(window.KKR);
